\newcommand{\myPentaPrism}[5]{
	\begin{scope}[scale=#5]
	    \def\StartAngle{5}	
    	\pgfmathsetmacro{\alpha}{360/5};  

		\coordinate (A0) at (#1,0,0);
		\coordinate (B0) at (#1,#2,0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+1*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+1*\alpha)/3};
		\coordinate (A1) at (\xc,\yc,0);
		\coordinate (B1) at (\xc,{\yc+#2},0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+2*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+2*\alpha)/3};
		\coordinate (A2) at (\xc,\yc,0);
		\coordinate (B2) at (\xc,{\yc+#2},0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+3*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+3*\alpha)/3};
		\coordinate (A3) at (\xc,\yc,0);
		\coordinate (B3) at (\xc,{\yc+#2},0);
			\pgfmathsetmacro{\xc}{#1*cos(\StartAngle+4*\alpha)};  
	    	\pgfmathsetmacro{\yc}{#1*sin(\StartAngle+4*\alpha)/3};
		\coordinate (A4) at (\xc,\yc,0);
		\coordinate (B4) at (\xc,{\yc+#2},0);
		\coordinate (S) at (0,#2,0);

		% Base
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](A0,A1,A2,A3,A4)

		% Faces
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A0,A1,B1,B0)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A1,A2,B2,B1)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A2,A3,B3,B2)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A3,A4,B4,B3)
		\tkzDrawPolygon[draw=none, fill=#3!15, fill opacity=#4](A4,A0,B0,B4)

		% Top
		\tkzDrawPolygon[draw=none, fill=#3!25, fill opacity=#4](B0,B1,B2,B3,B4)

		% Edges
		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](A0,A1 A1,A2)		
		\tkzDrawSegments[very thick, color=#3](A2,A3 A3,A4 A4,A0)	
		\tkzDrawSegments[very thick, color=#3](B0,B1 B1,B2 B2,B3 B3,B4 B4,B0)

		\tkzDrawSegments[thin, color=#3, dashed, opacity=0.75](B1,A1)
		\tkzDrawSegments[very thick, color=#3](B0,A0 B2,A2 B3,A3 B4,A4)

		%\tkzLabelPoints[above](S,A0,A1,A2,A3,A4);
		%\tkzLabelPoints[above](B0,B1,B2,B3,B4);
	\end{scope}
}

